def transform(grid):
    n, m = len(grid), len(grid[0])
    best = None
    best_count = -1
    # The output is the arrangement of the most concentrated 1s in a 3x3 window.
    for r in range(n - 2):
        for c in range(m - 2):
            count = sum(grid[i][j] == 1
                        for i in range(r, r + 3)
                        for j in range(c, c + 3))
            if count > best_count:
                best_count = count
                best = [[8 if grid[i][j] == 1 else 0
                         for j in range(c, c + 3)]
                        for i in range(r, r + 3)]
    return best
